const fs = require('fs'), path = require('path'), vm = require('vm');
const dir = '分析产出/持仓面板';
const https = require('https');
const BASES = ['https://cdn.bootcdn.net/ajax/libs/sql.js/1.13.0/', 'https://cdn.staticfile.org/sql.js/1.13.0/', 'https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/'];
function get(u) {
  return new Promise((res, rej) => {
    const r = https.get(u, { headers: { 'User-Agent': 'Mozilla/5.0' } }, x => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); return get(x.headers.location).then(res, rej); }
      const c = []; x.on('data', d => c.push(d)); x.on('end', () => res(Buffer.concat(c)));
    });
    r.on('error', rej); r.setTimeout(30000, () => r.destroy(new Error('timeout')));
  });
}
const els = {};
function el(id) {
  if (!els[id]) els[id] = { innerHTML: '', textContent: '', value: '', style: {}, dataset: {},
    classList: { toggle(){}, add(){}, remove(){}, contains(){ return false; } } };
  return els[id];
}
(async () => {
  let SQL = null;
  for (const base of BASES) {
    try {
      const wasm = await get(base + 'sql-wasm.wasm');
      if (wasm[0] !== 0x00 || wasm[1] !== 0x61) throw new Error('not wasm');
      const sb = { console, require, __dirname: process.cwd(), __filename: path.join(process.cwd(), '_s.js'),
        Uint8Array, Buffer, process, setTimeout, clearTimeout, WebAssembly,
        document: { getElementById: el, querySelector: s => el(s.replace(/^#/, '')), querySelectorAll: () => [], addEventListener(){} } };
      vm.createContext(sb);
      vm.runInContext((await get(base + 'sql-wasm.js')).toString('utf8'), sb);
      SQL = await sb.initSqlJs({ wasmBinary: new Uint8Array(wasm) });
      break;
    } catch (e) {}
  }
  if (!SQL) throw new Error('CDN failed');
  const dbPath = path.join(dir, 'holding.sqlite');
  const db = new SQL.Database(new Uint8Array(fs.readFileSync(dbPath)));
  const w = {}; vm.runInNewContext(fs.readFileSync(path.join(dir, 'config.js'), 'utf8'), { window: w, console });
  const cfg = w.PANEL_CONFIG;
  const now = new Date().toISOString();
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfg', JSON.stringify(cfg)]);
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSyncedAt', now]);
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSource', 'sync']);
  fs.writeFileSync(dbPath, Buffer.from(db.export()));
  console.log('SYNCED. targetYldFloor =', cfg.margin.targetYldFloor);
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

