const https = require('https');
function get(u) {
  return new Promise((res, rej) => {
    const r = https.get(u, { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://data.eastmoney.com/' } }, x => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); return get(x.headers.location).then(res, rej); }
      const c = []; x.on('data', d => c.push(d)); x.on('end', () => res(Buffer.concat(c).toString('utf8')));
    });
    r.on('error', rej); r.setTimeout(30000, () => r.destroy(new Error('timeout')));
  });
}
global.window = {};
require('./分析产出/持仓面板/config.js');
const cfg = window.PANEL_CONFIG;
const M = cfg.margin;

function secid(code) { return (code[0] === '6' ? '1.' : '0.') + code; }
function shiftDays(dateStr, days) {
  const d = new Date(dateStr + 'T00:00:00'); d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

(async () => {
  const rows = [];
  for (const t of cfg.targets) {
    try {
      const du = 'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_SHAREBONUS_DET&columns=ALL&filter=(SECURITY_CODE%3D%22' + t.code + '%22)&pageNumber=1&pageSize=100&sortColumns=EX_DIVIDEND_DATE&sortTypes=-1';
      const dj = JSON.parse(await get(du));
      const divs = ((dj.result && dj.result.data) || [])
        .filter(r => r.EX_DIVIDEND_DATE && +r.PRETAX_BONUS_RMB > 0)
        .map(r => ({ d: String(r.EX_DIVIDEND_DATE).slice(0, 10), v: +r.PRETAX_BONUS_RMB / 10 }))
        .sort((a, b) => a.d < b.d ? -1 : 1);
      const beg = new Date(Date.now() - ((M.pctYears || 3) * 365 + 40) * 864e5).toISOString().slice(0, 10).replace(/-/g, '');
      const ku = 'https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=' + secid(t.code) + '&fields1=f1,f2,f3,f4,f5&fields2=f51,f52,f53,f54,f55,f56&klt=101&fqt=0&beg=' + beg + '&end=20500101';
      const kj = JSON.parse(await get(ku));
      const raw = ((kj.data && kj.data.klines) || []).map(l => { const p = l.split(','); return { d: p[0], c: +p[2] }; });
      if (!raw.length) { rows.push({ t, err: 'no kline' }); continue; }
      const price = raw[raw.length - 1].c;
      const lastDate = raw[raw.length - 1].d;
      const startWin = shiftDays(lastDate, -Math.round((M.pctYears || 3) * 365));
      const hist = [];
      for (const r of raw) {
        if (r.d < startWin || !(r.c > 0)) continue;
        const cut = shiftDays(r.d, -365);
        const roll = divs.filter(x => x.d > cut && x.d <= r.d).reduce((a, x) => a + x.v, 0);
        if (roll > 0) hist.push(roll / r.c * 100);
      }
      const avg = hist.length ? hist.reduce((a, b) => a + b, 0) / hist.length : null;
      const dpsNow = divs.filter(x => x.d > shiftDays(lastDate, -365) && x.d <= lastDate).reduce((a, x) => a + x.v, 0);
      const curYld = dpsNow / price * 100;
      // 面板逻辑
      const pad = M.yldPadPct != null ? M.yldPadPct : 1;
      const floor = M.targetYldFloor != null ? M.targetYldFloor : (M.targetYld || 5);
      let tYld, how;
      if ((M.targetYldMode || 'dynamic') === 'fixed') { tYld = M.targetYldFixed != null ? M.targetYldFixed : floor; how = 'fixed'; }
      else if (avg != null && hist.length >= 250) {
        const rawv = avg + pad;
        if (rawv >= floor) { tYld = rawv; how = '均值+垫'; } else { tYld = floor; how = '下限'; }
      } else { tYld = floor; how = '样本不足→下限'; }
      const tb = dpsNow / (tYld / 100);
      rows.push({ t, price, dpsNow, curYld, avg, n: hist.length, tYld, how, tb, drop: (price - tb) / price * 100 });
    } catch (e) { rows.push({ t, err: e.message }); }
  }
  console.log('code  name       现价    dps    当前yld  3年均值  N     目标yld  来源       目标买价  需跌%');
  rows.forEach(r => {
    if (r.err) { console.log(r.t.code, r.t.name, 'ERR', r.err); return; }
    console.log(r.t.code, r.t.name.padEnd(8), String(r.price).padStart(6), r.dpsNow.toFixed(4).padStart(7),
      (r.curYld.toFixed(2) + '%').padStart(7), (r.avg != null ? r.avg.toFixed(2) + '%' : '-').padStart(8),
      String(r.n).padStart(4), (r.tYld.toFixed(2) + '%').padStart(8), r.how.padEnd(11),
      r.tb.toFixed(2).padStart(8), r.drop.toFixed(1).padStart(7));
  });
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

